SELECT ?z ?zname WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?zname .
  FILTER(CONTAINS(?zname, "ZN_4") || CONTAINS(?zname, "ZN_3"))
}

SELECT ?z ?zn ?part WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z ?zn ?part } .
  FILTER(CONTAINS(str(?z), "Perimeter") || CONTAINS(str(?z), "top"))
}
LIMIT 50

SELECT ?s ?n WHERE {
  ?n a brick:Zone .
  ?s ref:hasTimeseriesId ?t .
} 
LIMIT 5

SELECT ?z ?lbl WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?lbl .
  FILTER(CONTAINS(?lbl, "top"))
}

